// Шаги чата и блокировки для тестов взаимного матча (#b76c3b). Тексты — с кадров QA 29.10 (b76c3b-v-5b-*, b76c3b-v-5-blocked-list-*).
// Путь к списку чатов (/matches) и к «משתמשים חסומים» НЕ проверен автотестом — проверить при первом /qa-regress.
import { expect, type Page, type Response } from '@playwright/test';

export const NAMES = { free: 'QA חופשי', user4: 'רביעית' } as const;

const isWrite = (r: Response) => !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method());

// Открыть чат с партнёром: список мэтчей/чатов → строка с именем.
export async function openChat(page: Page, partnerName: string) {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('/matches');
  await page.getByText(partnerName).first().click();
  await expect(page.getByText(partnerName).first()).toBeVisible();
  await expect(page.getByRole('textbox').last()).toBeVisible();
}

// Отправить сообщение в открытом чате; вернуть ответ POST /rest/v1/messages.
export async function sendMessage(page: Page, text: string): Promise<Response> {
  const box = page.getByRole('textbox').last();
  await box.fill(text);
  const wait = page.waitForResponse((r) => r.url().includes('/rest/v1/messages') && r.request().method() === 'POST');
  const sendBtn = page.getByRole('button', { name: /שליחה|שלח|send/i });
  if (await sendBtn.count()) await sendBtn.last().click();
  else await box.press('Enter');
  return wait;
}

// В открытом чате: «•••» → «חסימת <имя>» → подтверждение «לחסום את <имя>?».
export async function blockFromChat(page: Page, partnerName: string) {
  await page.getByText('•••').or(page.getByRole('button', { name: /אפשרויות|עוד|more/i })).first().click();
  await expect(page.getByText('פעולות על הצ\'אט')).toBeVisible();
  await page.getByText(`חסימת ${partnerName}`).click();
  await expect(page.getByText(`לחסום את ${partnerName}?`)).toBeVisible();
  const wait = page.waitForResponse((r) => /block/i.test(r.url()) && isWrite(r));
  await page.getByRole('button', { name: /^חסימה$|^חסום/ }).or(page.getByText(/^חסימה$/)).last().click();
  expect((await wait).ok(), 'запрос блокировки 2xx').toBeTruthy();
}

// Профиль → «משתמשים חסומים» → «ביטול חסימה» (+ подтверждение, если есть). Безопасно, если блока уже нет.
export async function unblockAll(page: Page, partnerName: string) {
  await page.goto('/discover');
  await page.getByText('פרופיל', { exact: true }).last().click();
  const entry = page.getByText('משתמשים חסומים').first();
  if (!(await entry.isVisible())) {
    await page.getByRole('button', { name: /הגדרות|settings/i }).or(page.getByLabel(/הגדרות/)).first().click();
  }
  await entry.click();
  await expect(page.getByText('משתמשים חסומים').first()).toBeVisible();
  const row = page.getByText(partnerName);
  if (!(await row.count())) return;
  const wait = page.waitForResponse((r) => /block/i.test(r.url()) && isWrite(r));
  await page.getByText('ביטול חסימה', { exact: true }).first().click();
  const confirm = page.getByRole('button', { name: 'ביטול חסימה' });
  if ((await confirm.count()) > 1) await confirm.last().click();
  expect((await wait).ok(), 'запрос снятия блока 2xx').toBeTruthy();
  await expect(page.getByText(partnerName)).toHaveCount(0);
}
